#include <iostream>
#include <string>

struct Settings
{
    float volume{0.8f};
    bool fullscreen{false};
    std::string name{"player"};
    bool operator==(const Settings&) const = default;
};

class SettingsEditor
{
public:
    Settings& edit() { return m_edit; }
    bool dirty() const { return false; }

private:
    Settings m_applied{};
    Settings m_edit{};
};

int main()
{
    SettingsEditor e{};
    e.edit().volume = 0.5f;
    std::cout << e.dirty() << '\n';
}
